#!/usr/bin/env node/** * BANF CRM Admin ΓÇö Stage 1: Family Relationship Manager * ====================================================== * Aggregates all data sources ΓåÆ produces banf-crm-admin.html *   - banf-crm-reconciliation.json  (master reconciliation) *   - family-fix-mapping.json        (family agent fixes) *   - report_25-26_family_mapping.json (report-era mapping) * * The generated HTML is a fully self-contained SPA with: *   ΓÇó Family tree view with relationship editing *   ΓÇó Member CRUD (add / remove / rename / nickname) *   ΓÇó Universal search (name, nickname, phone, address) *   ΓÇó Full audit trail (admin name, timestamp, action details) *   ΓÇó LocalStorage persistence for offline edits */const fs = require('fs');const path = require('path');// ΓöÇΓöÇ Load data sources ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction loadJSON(f) {  try { return JSON.parse(fs.readFileSync(path.join(__dirname, f), 'utf8')); }  catch { return null; }}const recon  = loadJSON('banf-crm-reconciliation.json');const famFix = loadJSON('family-fix-mapping.json');const repMap = loadJSON('report_25-26_family_mapping.json');// External members-view JS (injected into <script> to avoid template-literal escaping issues)const membersViewCode = fs.readFileSync(path.join(__dirname, 'banf-crm-members-view.js'), 'utf8');// ΓöÇΓöÇ Aggregate ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst memberMap = new Map();   // email ΓåÆ memberconst familyMap = new Map();   // familyId ΓåÆ { id, displayName, type, members[] }function upsertMember(email, data) {  if (!email) return;  const key = email.toLowerCase().trim();  if (!memberMap.has(key)) {    memberMap.set(key, {      id: data.memberId || `MBR-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,6).toUpperCase()}`,      email: key,      firstName: '', lastName: '', displayName: '',      nickname: '',      phone: '', phone2: '',      address: '', city: '', state: '', zip: '',      gender: '', profession: '', employer: '', education: '',      dateOfBirth: '',      memberSince: '', memberType: 'adult',      isActive: true,      membershipYears: [], membershipTypes: [],      isECMember: false, isBOTMember: false,      totalPaid: 0,      orgRoles: [], volunteerEvents: [],      familyIds: [],      importSources: [],      notes: ''    });  }  const m = memberMap.get(key);  // Merge fields ΓÇö later source wins for non-empty values  if (data.firstName)  m.firstName = data.firstName;  if (data.lastName)   m.lastName  = data.lastName;  if (data.displayName) m.displayName = data.displayName;  if (data.phone)      m.phone     = data.phone;  if (data.phone2)     m.phone2    = data.phone2;  if (data.address)    m.address   = data.address;  if (data.city)       m.city      = data.city;  if (data.state)      m.state     = data.state;  if (data.zip)        m.zip       = data.zip;  if (data.gender)     m.gender    = data.gender;  if (data.profession) m.profession = data.profession;  if (data.employer)   m.employer  = data.employer;  if (data.education)  m.education = data.education;  if (data.dateOfBirth) m.dateOfBirth = data.dateOfBirth;  if (data.memberSince) m.memberSince = data.memberSince;  if (data.memberType) m.memberType = data.memberType;  if (data.isActive !== undefined) m.isActive = data.isActive;  if (data.isECMember) m.isECMember = true;  if (data.isBOTMember) m.isBOTMember = true;  if (data.totalPaid)  m.totalPaid = Math.max(m.totalPaid, data.totalPaid);  if (data.memberId && !m.id.startsWith('MBR-')) m.id = data.memberId;  if (data.memberId) m.id = data.memberId;  if (data.orgRoles) m.orgRoles = [...m.orgRoles, ...data.orgRoles];  if (data.volunteerEvents) m.volunteerEvents = [...m.volunteerEvents, ...data.volunteerEvents];  if (data.membershipYears) m.membershipYears = [...new Set([...m.membershipYears, ...data.membershipYears])];  if (data.membershipTypes) m.membershipTypes = [...new Set([...m.membershipTypes, ...data.membershipTypes])];  if (data.importSources) m.importSources = [...new Set([...m.importSources, ...data.importSources])];  if (!m.displayName && m.firstName) m.displayName = `${m.firstName} ${m.lastName}`.trim();  return m;}function upsertFamily(fid, data) {  if (!familyMap.has(fid)) {    familyMap.set(fid, {      id: fid,      displayName: data.displayName || '',      type: data.type || 'unknown',      memberEmails: [],      relationships: [],   // [{from, to, type}]      evidence: data.evidence || [],      source: data.source || 'aggregated'    });  }  const f = familyMap.get(fid);  if (data.displayName && !f.displayName) f.displayName = data.displayName;  if (data.type && f.type === 'unknown') f.type = data.type;  return f;}// 1) Master reconciliationif (recon && recon.members) {  for (const m of recon.members) {    upsertMember(m.email, m);    // Family grouping    if (m.familyId) {      const fam = upsertFamily(m.familyId, {        displayName: m.familyDisplayName,        type: m.familyType,        evidence: m.familyEvidence,        source: 'reconciliation'      });      if (!fam.memberEmails.includes(m.email.toLowerCase())) fam.memberEmails.push(m.email.toLowerCase());      const mem = memberMap.get(m.email.toLowerCase());      if (mem && !mem.familyIds.includes(m.familyId)) mem.familyIds.push(m.familyId);      // Add family member cross-refs      if (m.familyMembers) {        for (const fm of m.familyMembers) {          upsertMember(fm.email, fm);          const fmKey = fm.email?.toLowerCase();          if (fmKey && !fam.memberEmails.includes(fmKey)) fam.memberEmails.push(fmKey);          const fm2 = memberMap.get(fmKey);          if (fm2 && !fm2.familyIds.includes(m.familyId)) fm2.familyIds.push(m.familyId);        }      }    }    // Household grouping    if (m.householdId && m.householdId !== m.familyId) {      const hh = upsertFamily(m.householdId, {        displayName: m.householdDisplayName,        type: m.householdType,        evidence: m.householdEvidence,        source: 'household'      });      if (!hh.memberEmails.includes(m.email.toLowerCase())) hh.memberEmails.push(m.email.toLowerCase());      const mem = memberMap.get(m.email.toLowerCase());      if (mem && !mem.familyIds.includes(m.householdId)) mem.familyIds.push(m.householdId);    }  }}// 2) Family-fix mappingif (famFix && famFix.families) {  for (const ff of famFix.families) {    const fam = upsertFamily(ff.familyId, {      displayName: ff.displayName,      type: ff.familyType,      source: 'family-fix'    });    for (const fm of ff.members) {      upsertMember(fm.email, { memberId: fm.memberId, firstName: fm.firstName, lastName: fm.lastName });      const key = fm.email?.toLowerCase();      if (key && !fam.memberEmails.includes(key)) fam.memberEmails.push(key);      const mem = memberMap.get(key);      if (mem && !mem.familyIds.includes(ff.familyId)) mem.familyIds.push(ff.familyId);    }    // Infer couple relationship    if (ff.familyType === 'couple' && ff.members.length === 2) {      fam.relationships.push({        from: ff.members[0].email?.toLowerCase(),        to: ff.members[1].email?.toLowerCase(),        type: 'spouse'      });    }  }}// 3) Report family mappingif (repMap && repMap.mapping && repMap.mapping.families) {  for (const rf of repMap.mapping.families) {    const fam = upsertFamily(rf.family_id, {      displayName: rf.display_name,      type: rf.members.length > 2 ? 'family' : (rf.members.length === 2 ? 'couple' : 'individual'),      source: 'report-mapping'    });    for (const rm of rf.members) {      upsertMember(rm.email, { firstName: rm.firstName, displayName: rm.name });      const key = rm.email?.toLowerCase();      if (key && !fam.memberEmails.includes(key)) fam.memberEmails.push(key);      const mem = memberMap.get(key);      if (mem && !mem.familyIds.includes(rf.family_id)) mem.familyIds.push(rf.family_id);    }  }}// ΓöÇΓöÇ Deduplicate families using Union-Find on shared members ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Two families that share ANY member are considered the same real-world// family unit. We merge them into one canonical entry.const rawFamilies = [...familyMap.values()].filter(f => f.memberEmails.length > 0);// Union-Findconst parent = {};function ufFind(x) { return parent[x] === x ? x : (parent[x] = ufFind(parent[x])); }function ufUnion(a, b) { const ra = ufFind(a), rb = ufFind(b); if (ra !== rb) parent[rb] = ra; }rawFamilies.forEach(f => { parent[f.id] = f.id; });// Build email ΓåÆ family indexconst emailToFams = new Map();rawFamilies.forEach(f => {  f.memberEmails.forEach(e => {    if (!emailToFams.has(e)) emailToFams.set(e, []);    emailToFams.get(e).push(f.id);  });});// Union families that share any memberemailToFams.forEach((fids) => {  for (let i = 1; i < fids.length; i++) ufUnion(fids[0], fids[i]);});// Group families by rootconst groups = new Map();  // root ΓåÆ [family, ...]rawFamilies.forEach(f => {  const root = ufFind(f.id);  if (!groups.has(root)) groups.set(root, []);  groups.get(root).push(f);});// Merge each group into one canonical familyconst families = [];groups.forEach((group) => {  // Collect all unique member emails  const allEmails = [...new Set(group.flatMap(f => f.memberEmails))];  // Collect all relationships  const allRels = [];  const relSet = new Set();  group.forEach(f => f.relationships.forEach(r => {    const key = [r.from, r.to, r.type].sort().join('|');    if (!relSet.has(key)) { relSet.add(key); allRels.push(r); }  }));  // Collect all evidence  const allEvidence = group.flatMap(f => f.evidence || []);  // Collect source IDs for audit trail  const sourceIds = group.map(f => f.id);  // Pick best display name: prefer longer non-individual names, title-cased  const bestNameFam = group    .filter(f => f.displayName)    .sort((a, b) => {      // Prefer 'family' > 'couple' > 'individual'      const typePrio = { family: 3, couple: 2, individual: 1, unknown: 0 };      const ap = typePrio[a.type] || 0, bp = typePrio[b.type] || 0;      if (bp !== ap) return bp - ap;      return b.displayName.length - a.displayName.length;    })[0];  // Pick best type: prefer the most descriptive  const bestType = group.reduce((best, f) => {    const prio = { family: 3, couple: 2, individual: 1, unknown: 0, '': 0 };    return (prio[f.type] || 0) > (prio[best] || 0) ? f.type : best;  }, 'unknown');  // Canonical ID: prefer RFAM > FAM-2026 > HH > others  const canonId = group    .map(f => f.id)    .sort((a, b) => {      const prio = id => id.startsWith('RFAM') ? 3 : id.startsWith('FAM-2026') ? 2 : id.startsWith('HH') ? 1 : 0;      return prio(b) - prio(a);    })[0];  families.push({    id: canonId,    displayName: bestNameFam ? bestNameFam.displayName : '',    type: bestType,    memberEmails: allEmails,    relationships: allRels,    evidence: allEvidence,    source: 'merged (' + group.map(f => f.source).filter(Boolean).join(', ') + ')',    mergedFrom: sourceIds  });});// Reassign each member's familyIds to only reference canonical familiesconst canonicalIds = new Set(families.map(f => f.id));memberMap.forEach(m => {  // Map all old family IDs to their canonical root  const newFids = new Set();  m.familyIds.forEach(fid => {    const root = parent[fid] ? ufFind(fid) : fid;    // Find canonical family that contains this root    const canon = families.find(f => f.mergedFrom && f.mergedFrom.includes(root));    if (canon) newFids.add(canon.id);    else if (canonicalIds.has(fid)) newFids.add(fid);  });  m.familyIds = [...newFids];});const members = [...memberMap.values()].sort((a, b) => a.displayName.localeCompare(b.displayName));console.log(`   Before merge: ${rawFamilies.length} family records ΓåÆ After merge: ${families.length} canonical families`);// ΓöÇΓöÇ Statistics ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst stats = {  totalMembers: members.length,  totalFamilies: families.length,  activeFamilies: families.filter(f => f.memberEmails.some(e => memberMap.get(e)?.isActive)).length,  withPhone: members.filter(m => m.phone).length,  withAddress: members.filter(m => m.address || m.city).length,  ecMembers: members.filter(m => m.isECMember).length,  singles: families.filter(f => f.type === 'individual').length,  couples: families.filter(f => f.type === 'couple').length,  familyGroups: families.filter(f => f.type === 'family').length};console.log(`Γ£à Aggregated ${stats.totalMembers} members in ${stats.totalFamilies} families`);console.log(`   Couples: ${stats.couples} | Family groups: ${stats.familyGroups} | Individuals: ${stats.singles}`);// ΓöÇΓöÇ Generate HTML ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst dataJSON = JSON.stringify({ members, families, stats }, null, 0);const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>BANF CRM Admin ΓÇö Family & Member Management</title><style>/* ΓöÇΓöÇ CSS Reset & Variables ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */*{box-sizing:border-box;margin:0;padding:0}:root{  --bg:#0f1117;--surface:#1a1d27;--card:#232733;--border:#2d3348;  --text:#e4e6f0;--muted:#8b8fa3;--accent:#6366f1;--accent2:#818cf8;  --success:#22c55e;--warn:#f59e0b;--danger:#ef4444;--info:#3b82f6;  --radius:8px;--shadow:0 2px 12px rgba(0,0,0,.4);  --font:'Segoe UI','Inter',system-ui,sans-serif;}body{font-family:var(--font);background:var(--bg);color:var(--text);line-height:1.5;min-height:100vh}a{color:var(--accent2);text-decoration:none}/* ΓöÇΓöÇ Layout ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.app{display:flex;height:100vh;overflow:hidden}.sidebar{width:260px;background:var(--surface);border-right:1px solid var(--border);display:flex;flex-direction:column;flex-shrink:0}.sidebar-header{padding:16px 20px;border-bottom:1px solid var(--border)}.sidebar-header h1{font-size:1.1rem;font-weight:700;color:var(--accent2)}.sidebar-header p{font-size:.72rem;color:var(--muted);margin-top:2px}.sidebar-nav{flex:1;overflow-y:auto;padding:8px 0}.nav-item{display:flex;align-items:center;gap:10px;padding:10px 20px;cursor:pointer;font-size:.85rem;transition:.15s;border-left:3px solid transparent}.nav-item:hover{background:var(--card)}.nav-item.active{background:var(--card);border-left-color:var(--accent);color:var(--accent2)}.nav-item .icon{font-size:1.1rem;width:22px;text-align:center}.nav-badge{margin-left:auto;background:var(--accent);color:#fff;font-size:.68rem;padding:1px 7px;border-radius:10px}.main{flex:1;display:flex;flex-direction:column;overflow:hidden}.topbar{display:flex;align-items:center;gap:16px;padding:12px 24px;background:var(--surface);border-bottom:1px solid var(--border)}.topbar .admin-badge{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:.82rem}.topbar .admin-badge span{color:var(--muted)}.topbar .admin-name{color:var(--accent2);font-weight:600;cursor:pointer;padding:4px 10px;border:1px solid var(--border);border-radius:var(--radius)}.content{flex:1;overflow-y:auto;padding:24px}/* ΓöÇΓöÇ Search Bar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.search-bar{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}.search-input{flex:1;min-width:280px;padding:10px 16px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);font-size:.9rem;outline:none;transition:.2s}.search-input:focus{border-color:var(--accent)}.search-input::placeholder{color:var(--muted)}.search-filter{padding:8px 14px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);font-size:.82rem;cursor:pointer}.search-filter:hover,.search-filter.active{border-color:var(--accent);color:var(--accent2)}/* ΓöÇΓöÇ Cards & Panels ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin-bottom:24px}.stat-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;text-align:center}.stat-card .val{font-size:1.8rem;font-weight:700;color:var(--accent2)}.stat-card .lbl{font-size:.72rem;color:var(--muted);margin-top:2px}.panel{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:16px;overflow:hidden}.panel-header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--border);cursor:pointer}.panel-header h3{font-size:.92rem;font-weight:600}.panel-body{padding:16px 18px}/* ΓöÇΓöÇ Family Cards ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.family-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:16px}.family-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;transition:.2s}.family-card:hover{border-color:var(--accent);box-shadow:var(--shadow)}.family-card-header{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;background:rgba(99,102,241,.08);border-bottom:1px solid var(--border)}.family-card-header h4{font-size:.9rem;font-weight:600}.family-type-badge{font-size:.68rem;padding:2px 8px;border-radius:10px;font-weight:600}.family-type-badge.couple{background:rgba(236,72,153,.15);color:#ec4899}.family-type-badge.family{background:rgba(34,197,94,.15);color:#22c55e}.family-type-badge.individual{background:rgba(59,130,246,.15);color:#3b82f6}.family-card-body{padding:12px 16px}.family-member{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)}.family-member:last-child{border-bottom:none}.member-avatar{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.82rem;flex-shrink:0}.member-avatar.male{background:rgba(59,130,246,.2);color:#60a5fa}.member-avatar.female{background:rgba(236,72,153,.2);color:#f472b6}.member-avatar.unknown{background:rgba(139,143,163,.2);color:#8b8fa3}.member-info{flex:1;min-width:0}.member-name{font-size:.85rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.member-name .nickname{color:var(--warn);font-weight:400;font-style:italic;margin-left:6px}.member-email{font-size:.72rem;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.member-phone{font-size:.72rem;color:var(--info)}.family-card-actions{display:flex;gap:6px;padding:8px 16px;border-top:1px solid var(--border);justify-content:flex-end}/* ΓöÇΓöÇ Buttons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.btn{padding:6px 14px;border-radius:var(--radius);border:1px solid var(--border);background:var(--card);color:var(--text);font-size:.78rem;cursor:pointer;transition:.15s;display:inline-flex;align-items:center;gap:5px;font-family:var(--font)}.btn:hover{border-color:var(--accent);color:var(--accent2)}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.primary:hover{background:var(--accent2)}.btn.danger{border-color:var(--danger);color:var(--danger)}.btn.danger:hover{background:var(--danger);color:#fff}.btn.success{border-color:var(--success);color:var(--success)}.btn.success:hover{background:var(--success);color:#fff}.btn.sm{padding:4px 10px;font-size:.72rem}.btn.icon-btn{padding:4px 8px}/* ΓöÇΓöÇ Modal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:1000;display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:.2s}.modal-overlay.open{opacity:1;pointer-events:auto}.modal{background:var(--surface);border:1px solid var(--border);border-radius:12px;width:560px;max-width:95vw;max-height:85vh;display:flex;flex-direction:column;box-shadow:var(--shadow)}.modal-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--border)}.modal-header h3{font-size:1rem;font-weight:600}.modal-close{background:none;border:none;color:var(--muted);font-size:1.3rem;cursor:pointer;padding:4px}.modal-close:hover{color:var(--text)}.modal-body{padding:20px;overflow-y:auto;flex:1}.modal-footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 20px;border-top:1px solid var(--border)}/* ΓöÇΓöÇ Form ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */.form-group{margin-bottom:14px}.form-group label{display:block;font-size:.78rem;color:var(--muted);margin-bottom:4px;font-weight:500}.form-group input,.form-group select,.form-group textarea{width:100%;padding:8px 12px;background:var(--card);border:1px solid var(--border);border-radius:var(--radius);color:var(--text);font-size:.85rem;outline:none;font-family:var(--font)}.form-group input:focus,.form-group select:focus,.form-group textarea:focus{border-color:var(--accent)}.form-row{display:flex;gap:12px}.form-row .form-group{flex:1}.form-group textarea{resize:vertical;min-height:60px}/* ΓöÇΓöÇ Table ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ